INSERT INTO feature VALUES('machine-blocks','runtime','Machine blocks compiled from their description and entered by one transition',NULL,'partial','notable',NULL,'A block of machine code compiles from its description: the target, the template, each operand with its direction and its register or class, the registers that the template overwrites, and the options. The `llc` of the pinned toolchain assembles one LLVM function whose body is one inline-assembly call, in a process of its own, and the bytes are the text of its object. An object with a relocation, an undefined symbol or a second code section is refused by name. Each block is kept under the digest of its description, in the process and in a directory, so a second request starts no process. One stencil enters a block on both tiers: it writes the field of each machine integer operand into a word, calls the block under the C convention of the platform with the address of the words, and gives the answer of the block as a fresh machine integer, allocated before the call. A function names each block by its key, and a run maps the bytes of the block executable one time for the process before it starts, on a riscv64 host with no patcher too. A key that no compile gave, a block of another target and a host that refuses executable memory each decline the run by name. No surface form names a block yet (#7833).','runtime-emitter runtime-stencils','crates/runtime-emitter/tests/block.rs crates/runtime-emitter/src/machine.rs crates/runtime-stencils/tests/machine.rs','crate-tests','#7833');
